CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', average_lead_time_days numeric(10,2) NOT NULL DEFAULT 7, rating numeric(3,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id)); ALTER TABLE products ADD CONSTRAINT products_supplier_fk FOREIGN KEY (organization_id,preferred_supplier_id) REFERENCES suppliers(organization_id,id); CREATE INDEX suppliers_org_idx ON suppliers(organization_id);
